import json, statistics

files = {
    'Qwen DocRED greedy full (full_s1)': 'outputs/docred_full_s1.jsonl',
    'Llama DocRED greedy full': 'outputs/llama_docred_full_s1.jsonl',
    'Llama DocRED greedy mt6144': 'outputs/llama_docred_full_s1_mt6144.jsonl',
}

for name, fpath in files.items():
    try:
        times = []
        count = 0
        with open(fpath) as f:
            for line in f:
                count += 1
                d = json.loads(line)
                t = d.get('inference_time_seconds') or d.get('time_seconds') or d.get('generation_time')
                if t is not None:
                    times.append(float(t))
        if times:
            print(f'{name} | n={count} (timed={len(times)}) | total={sum(times):.1f}s | avg={statistics.mean(times):.3f}s | median={statistics.median(times):.3f}s')
        else:
            with open(fpath) as f:
                first = json.loads(f.readline())
            print(f'{name} | n={count} | NO TIMING | keys={list(first.keys())[:10]}')
    except Exception as e:
        print(f'{name} | ERROR: {e}')
